function pad(n){var s=String(n);while(s.length<6)s="0"+s;return s;}
function generate(seed){
  var s=prng(seed);var t=TOPICS[(seed-1)%TOPICS.length];
  return {
    id:PREFIX+"-"+pad(seed), name:t.name, title:t.title, description:t.description,
    genre:t.genre, type:t.type, content:t.content, content_completeness:"full",
    how_it_works:t.how_it_works, key_points:t.key_points, requirements:t.requirements,
    standards:t.standards, citations:t.citations, src:t.src,
    ladder_rank:t.ladder_rank, ladder_tier:t.ladder_tier,
    maturity:t.maturity, maturity_note:t.maturity_note, demo:t.demo, _seed:seed
  };
}
function validate(r){
  var errs=[];
  if(!r.id)errs.push("missing id");
  if(!r.title)errs.push("missing title");
  if(!r.description||r.description.length<200)errs.push("description too short");
  if(!r.demo)errs.push("missing demo");
  if(!r.maturity)errs.push("missing maturity");
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i].t===rec.title)return {ok:false,errors:["duplicate title"]};}
  return {ok:true,errors:[]};
}
if(typeof JAHDB!=="undefined"&&JAHDB.registerGenerator){JAHDB.registerGenerator("online-notable-opencode-2-signature",{generate:generate,validate:validate,driftCheck:driftCheck});}
else{var JAHDB=JAHDB||{};JAHDB.generators=JAHDB.generators||{};JAHDB.generators["online-notable-opencode-2-signature"]={generate:generate,validate:validate,driftCheck:driftCheck};}
if(typeof module!=="undefined"&&module.exports){module.exports={generate:generate,validate:validate,driftCheck:driftCheck};}
